import { lazy, Suspense, useState } from 'react';
import { Box, Download, RefreshCw } from 'lucide-react';
import type { ResourceConfig } from '../../config/schema';
import { resolveAssetUrl } from '../../config/loadConfig';
import { ImageViewer } from '../../features/archive/ImageViewer';
import '../../features/archive/archive.css';

// pdf.js 阅读器与三维查看器都很重，各自再懒一层（与旧 UI 的 ResourceViewer 一致）。
const PdfViewer = lazy(() => import('../../features/archive/PdfViewer'));
const ModelResourceViewer = lazy(() => import('../../features/devices/ModelResourceViewer'));

/** 同一批（同类型）资料的前后项：图片查看器用它做左右翻阅，PDF 用它做跳页。 */
export interface ResourceSiblings {
  /** 形如「3 / 6」。 */
  position?: string;
  prev?: ResourceConfig;
  next?: ResourceConfig;
  /** -1 = 上一项，1 = 下一项。 */
  onGo(offset: number): void;
}

/**
 * precision 的资料正文（图片 / 视频 / PDF / 三维资料）。
 *
 * **刻意不重写查看器**：捏合缩放、双击放大、前后翻阅、PDF 逐页渲染与跳页这些行为
 * 在旧 UI 的 `features/archive/*` 里已经调好（含真机手势的坑），precision 只换外壳——
 * 查看器本体原样复用，纸面语言由 `precision-viewer.css` 的 `.precision-viewer` 负责。
 *
 * 单独成模块的原因：`archive.css` 与 pdf.js 必须跟着"打开某份资料"这件事懒加载，
 * 不能挂进 precision 的首屏（档案列表页本身用不着它们）。
 */
export function PrecisionResourceViewer({ resource, siblings }: { resource: ResourceConfig; siblings?: ResourceSiblings }) {
  const [videoFailed, setVideoFailed] = useState(false);
  const url = resolveAssetUrl(resource.url);
  return (
    <div className="precision-viewer">
      {resource.kind === 'image' && (
        <ImageViewer
          src={url}
          alt={resource.title}
          position={siblings?.position}
          hasPrev={Boolean(siblings?.prev)}
          hasNext={Boolean(siblings?.next)}
          onPrev={siblings ? () => siblings.onGo(-1) : undefined}
          onNext={siblings ? () => siblings.onGo(1) : undefined}
          prevSrc={siblings?.prev ? resolveAssetUrl(siblings.prev.url) : undefined}
          nextSrc={siblings?.next ? resolveAssetUrl(siblings.next.url) : undefined}
        />
      )}
      {resource.kind === 'video' && !videoFailed && (
        <video
          src={url}
          poster={resource.poster ? resolveAssetUrl(resource.poster) : undefined}
          controls
          playsInline
          preload="metadata"
          onError={() => setVideoFailed(true)}
        />
      )}
      {resource.kind === 'video' && videoFailed && (
        <div className="media-fallback" role="alert">
          <strong>视频加载失败</strong>
          <button type="button" onClick={() => setVideoFailed(false)}><RefreshCw />重试</button>
          <a href={url} download><Download />下载视频</a>
        </div>
      )}
      {resource.kind === 'pdf' && (
        <Suspense fallback={<p className="viewer-loading">文档加载中</p>}>
          <PdfViewer url={url} />
        </Suspense>
      )}
      {resource.kind === 'model' && (
        <Suspense fallback={<div className="model-resource"><Box size={58} /><strong>三维模型资料</strong><span>正在启动三维查看器</span></div>}>
          <ModelResourceViewer resource={resource} />
        </Suspense>
      )}
    </div>
  );
}

export default PrecisionResourceViewer;
